package io.github.diodeme.ji.agent;

import io.github.diodeme.ji.ai.Usage;
import java.util.concurrent.CompletionStage;

/** Handle for one durable Session compaction operation. */
public interface AgentCompaction {
    String id();
    CompletionStage<Result> completion();
    boolean abort();

    record Result(String id, String summary, long tokensBefore, Usage usage) {
        public Result {
            if (id == null || id.isBlank() || summary == null || summary.isBlank()
                    || tokensBefore < 0 || usage == null) {
                throw new IllegalArgumentException("invalid compaction result");
            }
        }
    }
}
